// Phase 1 spike (throwaway). Modules: app (Kotlin, Spring Boot, Spark Connect client), rules (Scala, shared Spark API).
plugins {
	alias(libs.plugins.kotlin.jvm) apply false
	alias(libs.plugins.kotlin.spring) apply false
	alias(libs.plugins.spring.boot) apply false
}

/** spike/.env (generated by `make spike-env`), passed to test JVMs as environment variables. */
val spikeEnv: Map<String, String> = rootProject.file(".env").takeIf { it.exists() }?.readLines()
	?.filter { it.contains('=') && !it.startsWith("#") }
	?.associate { it.substringBefore('=') to it.substringAfter('=') } ?: emptyMap()
extra["spikeEnv"] = spikeEnv
